// WF-41 PDF-15 — 24h-window-aware relay payload builder.
// Window state comes from the upstream Postgres "Load Last Inbound" output ($json:
// { last_inbound, in_window }); the relay envelope is read from the always-run
// trigger node (post-Postgres $json is the query result, NOT the envelope).
const win = $input.first().json;
const env = $('When Executed by Another Workflow').first().json;

const phoneNumber = env.phoneNumber;
const messageText = env.messageText;
const userId = (env.user || {}).id || null;
const consultationId = (env.user || {}).current_consultation_id || null;

// in_window is computed in SQL (timestamptz vs NOW()). Read defensively: only an
// explicit true (boolean or string) counts as open; NULL / 0-row / anything else
// is treated as window-CLOSED so the always-deliverable template path is taken.
const inWindow = (win.in_window === true || win.in_window === 'true');

if (inWindow) {
  // Window OPEN — unchanged free-form behaviour (free per M1/M2).
  return [{
    json: {
      phoneNumber: phoneNumber,
      messageType: 'text',
      messageContent: messageText
    }
  }];
}

// Window CLOSED (or unknown) — out-window template path (DD-C).
// Template-safe per M4: no newlines/tabs, no runs of 4+ spaces, rendered body <= 1024.
const sanitized = String(messageText == null ? '' : messageText)
  .replace(/[\r\n\t]+/g, ' ')   // newlines / tabs -> single space
  .replace(/\s{2,}/g, ' ')        // collapse any run of 2+ whitespace -> one space
  .trim();

const TEMPLATE = 'astrology_service_update';
const MAX = 850;            // safety margin under Meta's 1024 body cap (fixed body text ~125 chars)
const LABEL_RESERVE = 12;   // room for a "(12/12) " style part label
const partMax = MAX - LABEL_RESERVE;

function buildItem(text) {
  return {
    json: {
      phoneNumber: phoneNumber,
      messageType: 'template',
      templateName: TEMPLATE,
      templateParams: [text],
      userId: userId,
      consultationId: consultationId
    }
  };
}

if (sanitized.length <= MAX) {
  return [buildItem(sanitized)];
}

// Split into <= partMax char parts on word boundaries; hard-split any single
// word that itself exceeds partMax.
function pushLong(parts, word) {
  let rest = word;
  while (rest.length > partMax) {
    parts.push(rest.slice(0, partMax));
    rest = rest.slice(partMax);
  }
  return rest;
}

const words = sanitized.split(' ');
const parts = [];
let cur = '';
for (const w of words) {
  if (cur === '') {
    cur = (w.length > partMax) ? pushLong(parts, w) : w;
  } else if ((cur.length + 1 + w.length) <= partMax) {
    cur += ' ' + w;
  } else {
    parts.push(cur);
    cur = (w.length > partMax) ? pushLong(parts, w) : w;
  }
}
if (cur !== '') parts.push(cur);

const N = parts.length;
return parts.map(function (p, i) {
  return buildItem('(' + (i + 1) + '/' + N + ') ' + p);
});

